"""Source-bound observations for NRS 484B.450(1)(c), not a legal evaluator.

The intersection polygon must come from a separately reviewed Native map packet.
Samples are original body footprints and motion records, not expected case labels.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path


class SourceError(ValueError):
    pass


def _require(condition: bool, message: str) -> None:
    if not condition:
        raise SourceError(message)


def load_source(path: Path, expected_sha256: str) -> dict:
    raw = path.read_bytes()
    _require(hashlib.sha256(raw).hexdigest() == expected_sha256,
             f"source seal differs: {path}")
    value = json.loads(raw)
    _require(isinstance(value, dict), f"source must be an object: {path}")
    return value


def _cross(a, b, c) -> float:
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


def _on_segment(a, b, p) -> bool:
    return abs(_cross(a, b, p)) <= 1e-9 and min(a[0], b[0]) - 1e-9 <= p[0] <= max(a[0], b[0]) + 1e-9 and min(a[1], b[1]) - 1e-9 <= p[1] <= max(a[1], b[1]) + 1e-9


def _segments_intersect(a, b, c, d) -> bool:
    if _on_segment(a, b, c) or _on_segment(a, b, d) or _on_segment(c, d, a) or _on_segment(c, d, b):
        return True
    return (_cross(a, b, c) > 0) != (_cross(a, b, d) > 0) and (_cross(c, d, a) > 0) != (_cross(c, d, b) > 0)


def _inside(point, polygon) -> bool:
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if _on_segment(a, b, point):
            return True
    crossings = 0
    x, y = point
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if (a[1] > y) != (b[1] > y):
            at_x = a[0] + (y - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            crossings += at_x > x
    return bool(crossings % 2)


def footprint_intersects_boundary(footprint, boundary) -> bool:
    """Count an overlapping body, including an edge touch, as boundary contact."""
    _require(len(footprint) >= 3 and len(boundary) >= 3, "missing body or intersection polygon")
    for polygon in (footprint, boundary):
        _require(all(len(p) == 2 and all(isinstance(v, (int, float)) for v in p) for p in polygon),
                 "invalid polygon coordinates")
    if any(_inside(p, boundary) for p in footprint) or any(_inside(p, footprint) for p in boundary):
        return True
    return any(_segments_intersect(a, b, c, d)
               for a, b in zip(footprint, footprint[1:] + footprint[:1])
               for c, d in zip(boundary, boundary[1:] + boundary[:1]))


def measure(boundary_packet: dict, samples_packet: dict, activity_packet: dict) -> dict:
    """Describe source-backed contact and halt intervals without legal labels."""
    for key in ("map_id", "highway_status", "boundary_method", "intersection_polygon", "source_refs"):
        _require(boundary_packet.get(key), f"missing reviewed intersection boundary: {key}")
    _require("joining_roadways" in boundary_packet,
             "missing reviewed intersection boundary: joining_roadways")
    _require(boundary_packet["highway_status"] == "reviewed_highway" and
             boundary_packet["joining_roadways"] is True,
             "intersection highway/joining-roadway basis unreviewed")
    boundary = boundary_packet["intersection_polygon"]
    _require(samples_packet.get("map_id") == boundary_packet["map_id"], "map identity differs")
    samples = samples_packet.get("samples", [])
    _require(len(samples) >= 2, "insufficient original motion samples")
    _require(activity_packet.get("source_refs") and activity_packet.get("activity_source"),
             "missing independent activity source")
    intervals = []
    last_frame = -1
    for sample in samples:
        frame = sample.get("frame")
        _require(isinstance(frame, int) and frame > last_frame, "nonmonotonic original frame")
        last_frame = frame
        _require(sample.get("body_footprint") and isinstance(sample.get("speed_mps"), (float, int)),
                 "missing original body or speed")
        intervals.append({"frame": frame,
                          "within_or_touching_boundary": footprint_intersects_boundary(
                              sample["body_footprint"], boundary),
                          "speed_mps": sample["speed_mps"]})
    _require(samples_packet.get("fps") == 20, "original 20 Hz frame basis missing")
    activity_samples = activity_packet.get("activity_samples")
    if activity_samples is not None:
        _require([row.get("frame") for row in activity_samples] == [row["frame"] for row in intervals],
                 "activity samples not joined to original frames")
        _require(all(row.get("source_ref") for row in activity_samples),
                 "activity sample original source missing")
    return {"map_id": boundary_packet["map_id"], "boundary_method": boundary_packet["boundary_method"],
            "frames": intervals, "activity_samples": activity_samples,
            "activity_observation": activity_packet.get("activity_observation"),
            "traffic_conflict_observation": activity_packet.get("traffic_conflict_observation"),
            "law_direction_observation": activity_packet.get("law_direction_observation"),
            "officer_direction_observation": activity_packet.get("officer_direction_observation"),
            "device_direction_observation": activity_packet.get("device_direction_observation"),
            "source_refs": boundary_packet["source_refs"] + samples_packet.get("source_refs", []) + activity_packet["source_refs"],
            "legal_conclusion": None}

"""Finalize original, sealed intersection observations into a nonlegal result.

Usage: python finalize_observables.py MANIFEST.json OUTPUT.json
The manifest's source paths resolve beside the manifest. It must be produced from
original map, Native trace, and independent activity/context packets.
"""

import json
import sys
from pathlib import Path

from intersection_observables import SourceError, load_source, measure


def finalize(manifest_path: Path) -> dict:
    manifest = json.loads(manifest_path.read_text())
    _case = manifest.get("case_id")
    if not isinstance(_case, str) or not _case:
        raise SourceError("missing exact case ID")
    packets = {}
    for name in ("boundary", "trace", "activity"):
        source = manifest.get(name)
        if not isinstance(source, dict) or not source.get("path") or not source.get("sha256"):
            raise SourceError(f"missing original {name} source and seal")
        path = (manifest_path.parent / source["path"]).resolve()
        if not path.is_relative_to(manifest_path.parent.resolve()):
            raise SourceError(f"original {name} source escapes attempt")
        packets[name] = load_source(path, source["sha256"])
    for name in ("trace", "activity"):
        if packets[name].get("case_id", _case) != _case:
            raise SourceError(f"original {name} case identity differs")
        if manifest.get("native_run_id") and packets[name].get("native_run_id") != manifest["native_run_id"]:
            raise SourceError(f"original {name} Native run identity differs")
    trace_frames = [row.get("frame") for row in packets["trace"].get("samples", [])]
    activity_samples = packets["activity"].get("activity_samples")
    if activity_samples is not None and [row.get("frame") for row in activity_samples] != trace_frames:
        raise SourceError("original activity/trace frame join differs")
    result = measure(packets["boundary"], packets["trace"], packets["activity"])
    return {"format": "intersection-observables-v1", "case_id": _case,
            "source_manifest": manifest_path.name, "source_seals": {
                name: manifest[name]["sha256"] for name in packets}, **result}


if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise SystemExit("usage: finalize_observables.py MANIFEST.json OUTPUT.json")
    result = finalize(Path(sys.argv[1]).resolve())
    Path(sys.argv[2]).write_text(json.dumps(result, indent=2) + "\n")

"""Source-bound saved intersection measurement without a legal conclusion."""
import argparse
import hashlib
import json
from pathlib import Path

from finalize_delivery import finalize_saved
from finalize_observables import finalize as finalize_original


def measure_intersection_contact(observations):
    frames = observations["frames"]
    return {"contact_frames": [row["frame"] for row in frames if row["within_or_touching_boundary"]],
            "frame_count": len(frames), "boundary_method": observations["boundary_method"]}


def measure_activity(observations):
    return {"original_observation": observations["activity_observation"],
            "independent_sample_count": len(observations["activity_samples"] or []),
            "legal_class": "unresolved"}


def measure_traffic_conflict(observations):
    return {"original_observation": observations["traffic_conflict_observation"],
            "necessity_judgment": "unresolved"}


def measure_law_direction(observations):
    return {"original_observation": observations["law_direction_observation"],
            "applicable_law_judgment": "unresolved"}


def measure_officer_direction(observations):
    return {"original_observation": observations["officer_direction_observation"],
            "compliance_judgment": "unresolved"}


def measure_device_direction(observations):
    return {"original_observation": observations["device_direction_observation"],
            "compliance_judgment": "unresolved"}


def analyze(attempt, case_id, contract):
    attempt = Path(attempt)
    contract = Path(contract)
    spec = json.loads(contract.read_text())
    if spec["case_id"] != case_id:
        raise ValueError("selected measurement contract case differs")
    for row in spec["requirements"]:
        for relative in row["inputs"]:
            if not (attempt / relative).is_file():
                raise ValueError("Missing required source: " + relative)
    diagnostic = (attempt / "acquisition-provenance.json").is_file() and json.loads(
        (attempt / "acquisition-provenance.json").read_text()).get("diagnostic_fixture") is True
    if diagnostic:
        diagnostic_manifest = attempt / "diagnostic-manifest.json"
        source_manifest = json.loads(diagnostic_manifest.read_text())
        if source_manifest.get("diagnostic_fixture") is not True:
            raise ValueError("compact fixture must declare synthetic provenance in its source seal")
        observations = finalize_original(diagnostic_manifest)
        saved = {"source_manifest_sha256": hashlib.sha256(diagnostic_manifest.read_bytes()).hexdigest()}
    else:
        saved = finalize_saved(attempt, expected_case=case_id)
        observations = saved["observations"]
    methods = {name: globals()[name] for name in (
        "measure_intersection_contact", "measure_activity", "measure_traffic_conflict",
        "measure_law_direction", "measure_officer_direction", "measure_device_direction")}
    measurements = {}
    for row in spec["requirements"]:
        sources = {name: hashlib.sha256((attempt / name).read_bytes()).hexdigest()
                   for name in row["inputs"]}
        measurements[row["output_key"]] = {"method": row["method"],
            "value": methods[row["method"]](observations), "sources": sources}
    report = {"case_id": case_id, "measurements": measurements,
            "source_manifest_sha256": saved["source_manifest_sha256"],
            "physical_completion_verified": False, "legal_conclusion": None}
    if (attempt / "config.json").is_file() and (attempt / "trace.jsonl").is_file():
        from worker_exchange.native_output import physical_result, validate_result
        config = json.loads((attempt / "config.json").read_text())
        description = json.loads((attempt / "construction.json").read_text())["recording_description"]
        trace = json.loads((attempt / "trace.json").read_text())["samples"]
        activity = json.loads((attempt / "activity.json").read_text())
        streams = {
            "activity_history": [row.get("activity_observation") or {"status": "unresolved"} for row in activity["activity_samples"]],
            "body_footprint_history": [row["body_footprint"] for row in trace],
            "traffic_conflict_history": [row.get("traffic_conflict_observation") or {"status": "unresolved"} for row in activity["activity_samples"]],
            "direction_history": [{"law": row.get("law_direction_observation"),
                                   "officer": row.get("officer_direction_observation"),
                                   "device": row.get("device_direction_observation")} for row in activity["activity_samples"]],
        }
        channel_dir = attempt / "channels"
        channel_dir.mkdir(exist_ok=True)
        evidence = []
        for channel in description["channels"]:
            name = channel["name"]
            path = channel_dir / (name + ".jsonl")
            with path.open("x") as output:
                for row, value in zip(trace, streams[name]):
                    output.write(json.dumps({"time_s": row["time_s"], "value": value}) + "\n")
            evidence.append({"name": name, "unit": channel["unit"],
                             "reference": str(path.relative_to(attempt))})
        context_path = channel_dir / "context.json"
        context_path.write_text(json.dumps({"intersection_geometry": json.loads((attempt / "boundary.json").read_text()),
                                            "applicable_law_source": {"status": "unresolved"}}) + "\n")
        for context in description["context_inputs"]:
            evidence.append({"name": context["name"], "unit": context["unit"],
                             "reference": str(context_path.relative_to(attempt))})
        target = {"target": "source-bound intersection observations", "requested": True,
                  "measured": bool(measurements), "method": "saved original source join", "tolerance": 0,
                  "matched": bool(measurements), "physical_cause_confirmed": False,
                  "cause_evidence": observations["source_seals"]}
        result = {"case_id": case_id, "measured_values": measurements,
                  "target_checks": [target], "setup_confirmed": False, "behavior_attempted": False,
                  "maneuver_completed": False, "termination_reason": "Saved source observations; legal judgment unresolved",
                  "physical_failure_flags": [], "trace_reference": "trace.jsonl",
                  "video_references": [name + ".mkv" for name in ("overview", "approach", "reference_corner", "driver_reference")],
                  "video_frame_map_reference": "video_frames.jsonl", "recording_description": description,
                  "recording_evidence": evidence, "realized_observables": {}}
        result = physical_result(attempt, result)
        validate_result(result)
        (attempt / "result.json").write_text(json.dumps(result, sort_keys=True, indent=2) + "\n")
    return report


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", required=True)
    parser.add_argument("--case")
    parser.add_argument("--contract")
    parser.add_argument("--output", required=True)
    args = parser.parse_args()
    attempt = Path(args.attempt)
    case_id = args.case
    if case_id is None:
        case_id = json.loads((attempt / "config.json").read_text())["selected_case_id"]
    contract = args.contract or attempt / "measurement-contract.json"
    result = analyze(attempt, case_id, contract)
    output = Path(args.output)
    if output.exists():
        raise ValueError("retain prior measurement output; choose fresh path")
    output.write_text(json.dumps(result, sort_keys=True, indent=2) + "\n")
    print("exact source-bound intersection measurements complete: " + case_id)


if __name__ == "__main__":
    main()

"""Independent source-join audit for one measured intersection comparison.

This checks source completeness and experimental isolation, not statutory status.
"""

from intersection_observables import SourceError


def audit(comparison: dict, left: dict, right: dict) -> dict:
    ids = comparison.get("case_ids", [])
    if len(ids) != 2 or [left.get("case_id"), right.get("case_id")] != ids:
        raise SourceError("comparison case identity differs")
    for name, record in (("left", left), ("right", right)):
        if not all(record.get("source_seals", {}).get(k) for k in ("boundary", "trace", "activity")):
            raise SourceError(f"{name} original source seals missing")
        if not record.get("frames") or not record.get("source_refs"):
            raise SourceError(f"{name} original observations missing")
    if left.get("map_id") != right.get("map_id") or left.get("source_seals", {}).get("boundary") != right.get("source_seals", {}).get("boundary"):
        raise SourceError("reviewed intersection boundary differs")
    left_conditions = left.get("condition_receipt", {})
    right_conditions = right.get("condition_receipt", {})
    fixed = comparison.get("fixed_condition_keys", [])
    changed = comparison.get("difference_keys", [])
    if not fixed or not changed:
        raise SourceError("comparison measurement contract missing")
    for key in fixed:
        if key not in left_conditions or key not in right_conditions:
            raise SourceError(f"fixed condition source missing: {key}")
        if left_conditions[key] != right_conditions[key]:
            raise SourceError(f"fixed condition differs: {key}")
    observed = []
    for key in changed:
        if key not in left_conditions or key not in right_conditions:
            raise SourceError(f"deliberate difference source missing: {key}")
        if left_conditions[key] != right_conditions[key]:
            observed.append(key)
    if not observed:
        raise SourceError("declared deliberate difference not observed")
    return {"format": "intersection-comparison-audit-v1",
            "comparison_id": comparison.get("comparison_id"), "case_ids": ids,
            "fixed_conditions_verified": fixed, "observed_difference_keys": observed,
            "legal_conclusion": None}

